CREATE TABLE `campaign_media` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `campaign_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `platform_content_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `media_type` enum('image','video') COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prompt` longtext COLLATE utf8mb4_unicode_ci,
  `local_path` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_size` bigint DEFAULT NULL,
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `duration_seconds` decimal(10,2) DEFAULT NULL,
  `status` enum('generating','completed','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'generating',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `media_stage` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'final',
  `watermarked` tinyint(1) DEFAULT '0',
  `logo_path` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logo_position` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logo_scale` float DEFAULT '100',
  `logo_opacity` float DEFAULT '100',
  `parent_media_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `watermark_config` longtext COLLATE utf8mb4_unicode_ci
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

