('0e4d61ba-c137-47ac-ac68-59b3d8777d2c', '7a24048a-e1e3-4bb0-ab1f-806490435f27', NULL, 'video', 'fal', 'minimax/h3-max-turbo/text-to-video', 'A short corporate video for Jade by JA Assure featuring a narrator explaining transit custody risk, showing jewellery in transit, risk assessment charts, and a CTA to register for the webinar. Clean corporate aesthetic, high contrast, professional. ', 'storage/campaigns/7a24048a-e1e3-4bb0-ab1f-806490435f27/video/reel_original_v1.mp4', 'reel_original_v1.mp4', 'video/mp4', 4640878, NULL, NULL, 5.00, 'completed', '2026-09-22 10:32:44', 'original', 0, NULL, NULL, 100, 100, NULL, NULL),
('1618fc63-d732-41a7-849e-51cfeb5a16b4', '638382c0-180c-4db3-9e58-27384681c1c6', NULL, 'video', 'fal', 'minimax/h3-max-turbo/text-to-video', 'Create a short promotional video for Jade by JA Assure. The video should open with a close‑up of a jewellery showcase, transition to a graphic of a secure transit route, overlay the event title \"Transit Custody Risk Mitigation for Jewellery Exhibitions\", date/time \"Sep 20 | 10 AM – 7 PM\", location \"Global Exhibition Hub, Singapore\", include a call‑to‑action button \"Register Now\", maintain a sophisticated, institutional tone, use muted gold and charcoal palette, high‑resolution, cinematic pacing.', 'storage/campaigns/638382c0-180c-4db3-9e58-27384681c1c6/video/reel_original_v1.mp4', 'reel_original_v1.mp4', 'video/mp4', 3571494, NULL, NULL, 5.00, 'completed', '2026-09-22 15:53:43', 'original', 0, NULL, NULL, 100, 100, NULL, NULL),
('24a9e698-2c4f-469e-9a49-147ebc6b20d8', 'c146f671-5657-4bc4-b9d5-0230de9e72c1', NULL, 'image', 'fal', 'google/nano-banana-2-lites', 'A professional event poster for Jade by JA Assure featuring the title \"Transit Custody Risk Mitigation Workshop\", date/time \"Oct 15, 2026 | 10:00 AM – 12:00 PM GMT+8\", location \"Virtual – via JA Assure platform\", free admission, high-security shipping container visual, clean modern sans-serif typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'storage/campaigns/c146f671-5657-4bc4-b9d5-0230de9e72c1/image/original_v1.png', 'original_v1.png', 'image/png', 1284270, NULL, NULL, NULL, 'completed', '2026-09-22 18:24:25', 'original', 0, NULL, NULL, 100, 100, NULL, NULL),
('254e7be2-2889-461a-8f10-7b3b38d762ce', 'c146f671-5657-4bc4-b9d5-0230de9e72c1', NULL, 'image', 'local_composer', 'watermark-composer', 'A professional event poster for Jade by JA Assure featuring the title \"Transit Custody Risk Mitigation Workshop\", date/time \"Oct 15, 2026 | 10:00 AM – 12:00 PM GMT+8\", location \"Virtual – via JA Assure platform\", free admission, high-security shipping container visual, clean modern sans-serif typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'storage/campaigns/c146f671-5657-4bc4-b9d5-0230de9e72c1/image/final_v3.png', 'final_v3.png', 'image/png', 1893954, NULL, NULL, NULL, 'completed', '2026-09-22 18:33:35', 'final', 1, '/logo/doctorshield.png', 'custom', 80, 90, '24a9e698-2c4f-469e-9a49-147ebc6b20d8', '\"{\\\"logos\\\": [{\\\"id\\\": \\\"logo-primary\\\", \\\"name\\\": \\\"DoctorShield\\\", \\\"anchor\\\": \\\"custom\\\", \\\"scale\\\": 80, \\\"opacity\\\": 90, \\\"x\\\": 78, \\\"y\\\": 87}], \\\"custom_text\\\": null, \\\"primary_anchor\\\": \\\"custom\\\", \\\"primary_scale\\\": 80, \\\"primary_opacity\\\": 90}\"'),
