('7e172d54-c075-480b-b76c-54f5b42e4999', 'b47983f0-6c8b-4e8b-a74c-9ff843eb8b7e', NULL, 'video', 'local_composer', 'watermark-composer', 'Create a 30‑second promotional video for Jade’s free webinar on transit custody risk. Start with a scene of a jewellery display on a transit truck, transition to a lockbox and GPS tracker, overlay webinar details (title, date, time, virtual format, free registration). Include a concise voiceover explaining the importance of understanding transit risk and the benefits of attending. End with a clear call‑to‑action button: \"Register Now\". Use clean corporate visuals, muted colour palette, and professional narration.', 'storage/campaigns/b47983f0-6c8b-4e8b-a74c-9ff843eb8b7e/video/reel_final_v1.mp4', 'reel_final_v1.mp4', 'video/mp4', 2587551, NULL, NULL, NULL, 'completed', '2026-09-22 10:05:47', 'final', 1, NULL, 'top-left', 80, 90, '92d0fd1e-caa5-4c3b-804d-7497a13699e1', NULL),
