('92d0fd1e-caa5-4c3b-804d-7497a13699e1', 'b47983f0-6c8b-4e8b-a74c-9ff843eb8b7e', NULL, 'video', 'fal', 'minimax/h3-max-turbo/text-to-video', 'Create a 30‑second promotional video for Jade’s free webinar on transit custody risk. Start with a scene of a jewellery display on a transit truck, transition to a lockbox and GPS tracker, overlay webinar details (title, date, time, virtual format, free registration). Include a concise voiceover explaining the importance of understanding transit risk and the benefits of attending. End with a clear call‑to‑action button: \"Register Now\". Use clean corporate visuals, muted colour palette, and professional narration.', 'storage/campaigns/b47983f0-6c8b-4e8b-a74c-9ff843eb8b7e/video/reel_original_v1.mp4', 'reel_original_v1.mp4', 'video/mp4', 5539296, NULL, NULL, 5.00, 'completed', '2026-09-22 10:04:27', 'original', 0, NULL, NULL, 100, 100, NULL, NULL),
('a2c6c3a9-07aa-4d82-9d7b-595d4b56ee49', '5e21e31a-16f1-4768-84ef-e13c5eff7f9c', NULL, 'image', 'demo_local', 'google/nano-banana-2-lites', 'Commercial advertising poster with bold typography text overlay for Jade by JA Assure. Large prominent headline text overlay across the top reads: \"JADE VAULT AUDIT 2026\". Secondary sub-headline text overlay reads: \"OCT 15 | MARINA BAY SINGAPORE\". Third line text reads: \"COMPLIMENTARY EXECUTIVE BRIEFING\". High-contrast luxury graphic design poster layout with clean typography text overlay on an editorial photograph of a high-security titanium vault with sparkling emeralds and diamond necklaces.', 'storage/campaigns/5e21e31a-16f1-4768-84ef-e13c5eff7f9c/image/poster_v1.png', 'poster_v1.png', 'image/png', 4208, NULL, NULL, NULL, 'completed', '2026-09-22 07:28:50', 'final', 0, NULL, NULL, 100, 100, NULL, NULL),
