('de39b122-bdf3-4ee1-bcb6-99a794a24142', 'c146f671-5657-4bc4-b9d5-0230de9e72c1', NULL, 'image', 'local_composer', 'watermark-composer', 'A professional event poster for Jade by JA Assure featuring the title \"Transit Custody Risk Mitigation Workshop\", date/time \"Oct 15, 2026 | 10:00 AM – 12:00 PM GMT+8\", location \"Virtual – via JA Assure platform\", free admission, high-security shipping container visual, clean modern sans-serif typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'storage/campaigns/c146f671-5657-4bc4-b9d5-0230de9e72c1/image/final_v1.png', 'final_v1.png', 'image/png', 1284270, NULL, NULL, NULL, 'completed', '2026-09-22 18:30:14', 'final', 1, '/logo/jaguar.png', 'bottom-right', 80, 90, '24a9e698-2c4f-469e-9a49-147ebc6b20d8', '\"{\\\"logos\\\": [{\\\"id\\\": \\\"logo-primary\\\", \\\"logo_path\\\": \\\"/logo/jaguar.png\\\", \\\"name\\\": \\\"Jaguar Transit\\\", \\\"file\\\": null, \\\"filename\\\": null, \\\"src\\\": null, \\\"url\\\": null, \\\"anchor\\\": \\\"custom\\\", \\\"scale\\\": 80.0, \\\"opacity\\\": 90.0, \\\"x\\\": 44.0, \\\"y\\\": 74.0}], \\\"custom_text\\\": null, \\\"primary_anchor\\\": \\\"bottom-right\\\", \\\"primary_scale\\\": 80.0, \\\"primary_opacity\\\": 90.0}\"'),
