INSERT INTO `campaign_platform_content` (`id`, `campaign_id`, `platform`, `title`, `content`, `hashtags`, `hook`, `script`, `captions`, `visual_concept`, `image_generation_prompt`, `video_generation_prompt`, `language`, `created_at`, `updated_at`, `version`, `is_current`) VALUES
('045695b6-2479-4d62-8343-dc875ec97476', '3cb539ff-5993-4fc0-ad9d-18d3e2d4a7fe', 'blog', 'The Specialist Approach to Jewellery Risk Protection', 'Jewellery businesses operate in a high‑value, high‑risk environment. Theft, loss, market swings, and regulatory shifts can threaten even the most carefully curated collections. Traditional insurance often fails to address the specific challenges of precious metals, gemstones, and fine art. At Jade, we bring specialised expertise, deep industry knowledge, and tailored coverage options that recognise the unique vulnerabilities of jewellery assets. In this article we explore the key risk factors, the importance of a specialist partnership, and practical steps you can take to safeguard your business. By understanding the risks and engaging a specialist insurer, you can focus on what you do best—creating beauty—while knowing your assets are protected in a measured, informed way.', '[]', NULL, NULL, NULL, NULL, 'A professional event poster for Jade by JA Assure featuring the title \"Jade Risk Protection Webinar: Protecting Your Precious Collections\", date/time \"Oct 15, 2024 | 3:00 PM – 4:30 PM GMT\", location \"Online – Virtual Conference\", elegant image of a jeweller beside a secure vault, clean modern sans-serif typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'Create a 30‑second promotional video for the Jade Risk Protection Webinar. Start with a close‑up of a jeweller handling a gem, transition to a graph showing risk statistics, overlay text: \'Protect Your Collection\', include Jade logo and webinar details (Oct 15, 3:00 PM – 4:30 PM GMT, Online). End with a call‑to‑action: \'Reserve Your Spot – Free Webinar\'. Use a sophisticated, muted colour palette, professional voiceover with authoritative tone, and crisp text overlays.', 'en', '2026-09-22 18:05:42', '2026-09-22 18:05:42', 1, 1),
('0615eeab-9234-4f90-bf58-cf1ca1d3fae6', 'ec1ccb12-abde-40f1-a316-0dec519d26b0', 'reel', 'Protect Your Showcase: Transit Custody Risk 101', 'Did you know that 30% of high‑value pieces are lost or damaged during transit to exhibitions? Let’s change that.', '[]', 'Did you know that 30% of high‑value pieces are lost or damaged during transit to exhibitions? Let’s change that.', 'Scene 1: Opening shot of a bustling exhibition hall with jewellery displays. Voiceover: “High‑value jewellery and fine art face significant risk when travelling to regional exhibitions.”\nScene 2: Close‑up of a security expert in a shipping container. Voiceover: “Key threats include handling errors, security breaches, and environmental exposure.”\nScene 3: Visual of secure packaging and tracking technology. Voiceover: “Effective risk mitigation starts with proper packaging, real‑time tracking, and the right coverage.”\nScene 4: On‑screen text with event details and CTA. Voiceover: “Join Jade’s free workshop on Oct 15 at Marina Bay Sands to learn how to protect your assets. Register now.”', 'Protect Your Showcase: Transit Custody Risk 101 – Join us Oct 15 at Marina Bay Sands – Free Admission – Register Now', '[{\"scene\": 1, \"visual\": \"Bustling exhibition hall with jewellery displays\", \"duration\": \"5s\"}, {\"scene\": 2, \"visual\": \"Security expert inside a secure shipping container\", \"duration\": \"4s\"}, {\"scene\": 3, \"visual\": \"Secure packaging and tracking tech in action\", \"duration\": \"5s\"}, {\"scene\": 4, \"visual\": \"Event details overlay: Transit Custody Risk Management Workshop, Oct\\u202f15, 9\\u202fAM \\u2013 4\\u202fPM, Marina Bay Sands, Free Admission\", \"duration\": \"5s\"}]', 'A professional event poster for Jade by JA Assure featuring the title \"Transit Custody Risk Management Workshop\", date/time \"Oct 15, 2024 | 9 AM – 4 PM\", location \"Marina Bay Sands, Singapore\", a high-security exhibition environment with jewellery displays and a secure shipping container, clean modern typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'Create a 30‑second promotional video for Jade’s Transit Custody Risk Management Workshop. The video should open with a dynamic shot of an exhibition hall, transition to a security expert inside a secure shipping container, showcase secure packaging and real‑time tracking technology, and end with event details overlay: title \"Transit Custody Risk Management Workshop\", date \"Oct 15, 2024\", time \"9 AM – 4 PM\", location \"Marina Bay Sands, Singapore\", and call to action \"Register Now – Free Admission\". Use corporate aesthetic, clean typography, and subtitles. The tone should be authoritative, educational, and risk‑aware, avoiding any guarantee of protection. Include a voiceover script that matches the reel script above.', 'en', '2026-09-22 08:56:25', '2026-09-22 08:56:25', 1, 1),
('06e8fbcd-6d07-4381-8cb9-f50a87bb4773', 'b47983f0-6c8b-4e8b-a74c-9ff843eb8b7e', 'linkedin', 'Reduce Transit Custody Risk for Jewellery Exhibitions – Join Our Free Webinar', 'Regional exhibitions bring incredible exposure – but they also introduce significant transit risks. Jade Assure’s experts will walk you through the key threats, risk‑mitigation strategies, and best‑practice underwriting partnerships that protect your assets from the moment they leave the showroom to the moment they return. This is a no‑sales, educational session designed for jewellers, fine‑art businesses, and luxury asset owners who want to understand the full scope of transit risk.\n\n📅 Oct 15, 2024 • 2 PM – 4 PM UTC • Virtual\n\n👉 Register now: https://jaassure.com/jade-webinar', '[\"#JewelleryRisk\", \"#ExhibitionSecurity\", \"#JadeAssure\", \"#LuxuryAssetProtection\"]', NULL, NULL, NULL, NULL, 'A professional event poster for Jade by JA Assure featuring the title \"Transit Custody Risk Management for Jewellery Exhibitions\", date/time \"Oct 15, 2024 | 2:00 PM – 4:00 PM UTC\", location \"Virtual Webinar (Zoom)\", a stylised illustration of a jewellery display on a transit truck with a secure lockbox and GPS tracker overlay, clean modern sans-serif typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'Create a 30‑second promotional video for Jade’s free webinar on transit custody risk. Start with a scene of a jewellery display on a transit truck, transition to a lockbox and GPS tracker, overlay webinar details (title, date, time, virtual format, free registration). Include a concise voiceover explaining the importance of understanding transit risk and the benefits of attending. End with a clear call‑to‑action button: \"Register Now\". Use clean corporate visuals, muted colour palette, and professional narration.', 'en', '2026-09-22 10:04:06', '2026-09-22 10:04:06', 1, 1),
('099404d5-a317-4f10-a99c-7f99c74b925a', '9007a646-1ad3-48ed-b3fd-3512cd6e36e0', 'linkedin', 'Risk Management for Luxury Assets: A Practical Workshop', 'In today’s complex market, the protection of high‑value jewelry and fine art requires a clear understanding of risk and a partnership with a specialist insurer. Join us on Sep 25 for an in‑depth workshop led by Jade’s underwriting experts, who will walk you through the key factors that influence coverage, how to assess your assets, and what to expect from a policy. This session is designed for jewellery retailers, fine‑art businesses, and luxury asset owners who want to make informed decisions rather than rely on generic solutions.\n\nThe workshop will cover:\n• Identification of the most common threats to luxury assets\n• Practical steps to mitigate risk before you sign a policy\n• How to work with a specialist insurer to align coverage with your unique needs\n\nNo promises of zero loss—just a partnership grounded in expertise and realistic risk management.\n\nReserve your seat now and take the first step toward a more secure future for your most valuable assets.', '[\"#JewelleryRisk\", \"#AssetProtection\", \"#JadeAssure\"]', NULL, NULL, NULL, NULL, 'A professional event poster for Jade by JA Assure featuring the title \"Safeguarding Your Jewelry: Risk Management Workshop\", date/time \"Sep 25, 10 AM – 4 PM\", location \"Jade Conference Centre, London\", a subtle silhouette of a jeweler with sparkling gems and a faint security lock icon, clean modern sans‑serif typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'A short promotional video (30‑seconds) that opens with a close‑up of a jeweler’s shop, transitions to an animated risk matrix, then displays the workshop invitation with title, date, time, location, and registration URL, concluding with the Jade logo and tagline. The video uses a warm color palette, clean transitions, and a professional voiceover that explains risk awareness and invites viewers to register. The final frame includes a call‑to‑action: \"Register at jade.com/events\".', 'en', '2026-09-22 18:09:47', '2026-09-22 18:09:47', 1, 1),
('1615f11b-5f42-4b9e-ad94-7b91e62c5b36', 'ec1ccb12-abde-40f1-a316-0dec519d26b0', 'x', NULL, 'Transits to exhibitions expose jewellery and fine art to significant risk. Learn how to minimise that risk at our free workshop on Oct 15, 2024 at Marina Bay Sands. Register now – spots are limited. #JadeAssure #TransitRisk', '[\"#JewellerySecurity\", \"#FineArtProtection\", \"#TransitRisk\"]', NULL, NULL, NULL, NULL, 'A professional event poster for Jade by JA Assure featuring the title \"Transit Custody Risk Management Workshop\", date/time \"Oct 15, 2024 | 9 AM – 4 PM\", location \"Marina Bay Sands, Singapore\", a high-security exhibition environment with jewellery displays and a secure shipping container, clean modern typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'Create a 30‑second promotional video for Jade’s Transit Custody Risk Management Workshop. The video should open with a dynamic shot of an exhibition hall, transition to a security expert inside a secure shipping container, showcase secure packaging and real‑time tracking technology, and end with event details overlay: title \"Transit Custody Risk Management Workshop\", date \"Oct 15, 2024\", time \"9 AM – 4 PM\", location \"Marina Bay Sands, Singapore\", and call to action \"Register Now – Free Admission\". Use corporate aesthetic, clean typography, and subtitles. The tone should be authoritative, educational, and risk‑aware, avoiding any guarantee of protection. Include a voiceover script that matches the reel script above.', 'en', '2026-09-22 08:56:25', '2026-09-22 08:56:25', 1, 1),
('16d80c0a-200d-4b05-a23e-d29eef79e49b', '7a90d326-ce6e-487f-9f00-ee8dbcf2c4da', 'blog', 'Understanding Risk in the Jewellery Industry: A Specialist Perspective', 'The jewellery industry operates at the intersection of artistry, luxury, and high-value assets. While the allure of exquisite pieces captivates customers, the inherent risks—stolen inventory, accidental damage, market volatility—require a nuanced approach to protection. Jade, a specialist in jewellery and fine‑art risk management, offers a framework that goes beyond traditional insurance. Through detailed risk assessments, tailored underwriting, and an ongoing partnership model, we help jewellers identify vulnerabilities, understand coverage scopes, and implement proactive measures. This blog explores common risk scenarios, the importance of specialized knowledge, and how a partnership with Jade can enhance your risk‑management strategy. We emphasize that protection is an informed partnership rather than a guaranteed outcome, aligning with industry best practices and regulatory expectations. Read on to gain insights that can safeguard your business and preserve the value of your precious assets.\n\nKey Takeaways:\n1. Identify the unique risks specific to jewellery retail and storage.\n2. Understand the limits of standard insurance policies.\n3. Leverage specialist underwriting for tailored coverage.\n4. Adopt proactive loss‑prevention measures.\n5. Engage in continuous risk education and partnership.\n\nBy embracing a specialist risk‑management approach, jewellers can protect their assets, maintain customer confidence, and navigate market uncertainties with confidence.', '[]', NULL, NULL, NULL, NULL, 'A professional event poster for Jade by JA Assure featuring the title \"Specialist Jewellery Risk Protection Webinar\", date/time \"Oct 15, 2024 | 2:00 PM – 3:30 PM GMT\", location \"Online – Webinar\", visual scene description: a stylised diamond against a muted metallic gradient background, clean modern sans‑serif typography, high contrast between text and background, crisp readable lettering, corporate aesthetic graphic design poster layout.', 'Create a 30‑second promotional video for the Specialist Jewellery Risk Protection Webinar. Opening with a close‑up of a diamond, transition to quick cuts of theft, fire, and market decline. Include Jade logo and risk icons. Overlay text: \"Specialist Jewellery Risk Protection Webinar | Oct 15, 2024 | 2:00 PM – 3:30 PM GMT | Online – Webinar | Free | Register Now\". Voiceover script: \"Every jewel tells a story, but behind the sparkle lies risk. Theft, fire, market volatility—these are real threats. At Jade, we partner with jewellers to understand these risks and craft tailored solutions—no guarantees, just informed protection. Join our free webinar on Oct 15. Secure your future, one informed decision at a time.\" End with a call‑to‑action button \"Register Now\" and Jade branding. Use a sophisticated, muted color palette with subtle gold accents. Ensure clear, crisp visuals and smooth transitions. Render in high definition.', 'en', '2026-09-22 18:07:01', '2026-09-22 18:07:01', 1, 1),
('19d8ab45-71ac-4650-be37-c95ccc5b9dc0', 'c1b2c074-db24-4aa5-af75-7e9df9e18d78', 'x', NULL, 'High-value inventory risk isn\'t just about vault thickness—it\'s about protocol redundancy at handover points.\n\nHow does your atelier manage off-site client viewings? Read our underwriting brief: jaassure.com/jade', '[\"#JewelleryRisk\", \"#LuxurySecurity\"]', NULL, NULL, NULL, NULL, 'Commercial advertising poster with bold typography text overlay for Jade by JA Assure. Large prominent headline text overlay across the top reads: \"JADE VAULT AUDIT 2026\". Secondary sub-headline text overlay reads: \"OCT 15 | MARINA BAY SINGAPORE\". Third line text reads: \"COMPLIMENTARY EXECUTIVE BRIEFING\". High-contrast luxury graphic design poster layout with clean typography text overlay on an editorial photograph of a high-security titanium vault with sparkling emeralds and diamond necklaces.', 'Cinematic vertical 9:16 shot of an armoured courier in elegant black uniform locking a biometric titanium transit case, moving steadily through a private gallery corridor, professional high-end lighting, seamless slow motion', 'en', '2026-09-22 07:50:26', '2026-09-22 07:50:26', 1, 1),
