('168e3635-60e2-4847-8f18-944590e5090d', '5e21e31a-16f1-4768-84ef-e13c5eff7f9c', 'reel', 'queued', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-23 00:40:13', '2026-09-23 00:40:13', 'buffer', NULL),
('1885a3b9-af9d-42da-9fcf-1a855bb25106', 'b47983f0-6c8b-4e8b-a74c-9ff843eb8b7e', 'linkedin', 'published', '6ab253335cfcad806a386bc2', 'https://publish.buffer.com/organization/6ab21db8f343178ecdc4c6d2/queue', 'Regional exhibitions bring incredible exposure – but they also introduce significant transit risks. Jade Assure’s experts will walk you through the key threats, risk‑mitigation strategies, and best‑practice underwriting partnerships that protect your assets from the moment they leave the showroom to the moment they return. This is a no‑sales, educational session designed for jewellers, fine‑art businesses, and luxury asset owners who want to understand the full scope of transit risk.\n\n📅 Oct 15, 2024 • 2 PM – 4 PM UTC • Virtual\n\n👉 Register now: https://jaassure.com/jade-webinar\n\n#JewelleryRisk #ExhibitionSecurity #JadeAssure #LuxuryAssetProtection', NULL, NULL, '2026-09-22 15:36:43', '2026-09-22 15:36:33', '2026-09-22 15:36:43', 'buffer', NULL),
